/* Model terminate function */
void Copy_of_TRACKING_CONTROL_KPES_terminate(void)
{
  /* Terminate for S-Function (hil_initialize_block): '<Root>/HIL Initialize' */

  /* S-Function Block: Copy_of_TRACKING_CONTROL_KPES/HIL Initialize (hil_initialize_block) */
  {
    t_boolean is_switching;
    t_int result;
    t_uint32 num_final_analog_outputs = 0;
    t_uint32 num_final_digital_outputs = 0;
    hil_task_stop_all(Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card);
    hil_monitor_stop_all(Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card);
    is_switching = false;
    if ((Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_AOTerminate &&
         !is_switching) || (Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_AOExit
         && is_switching)) {
      {
        int_T i1;
        real_T *dw_AOVoltages =
          &Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_AOVoltages[0];
        for (i1=0; i1 < 8; i1++) {
          dw_AOVoltages[i1] =
            Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_AOFinal;
        }
      }

      num_final_analog_outputs = 8U;
    }

    if ((Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_DOTerminate &&
         !is_switching) || (Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_DOExit
         && is_switching)) {
      {
        int_T i1;
        boolean_T *dw_DOBits =
          &Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_DOBits[0];
        for (i1=0; i1 < 9; i1++) {
          dw_DOBits[i1] = Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_DOFinal;
        }
      }

      num_final_digital_outputs = 9U;
    }

    if (0
        || num_final_analog_outputs > 0
        || num_final_digital_outputs > 0
        ) {
      /* Attempt to write the final outputs atomically (due to firmware issue in old Q2-USB). Otherwise write channels individually */
      result = hil_write(Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card
                         ,
                         Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_AOChannels,
                         num_final_analog_outputs
                         , NULL, 0
                         ,
                         Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_DOChannels,
                         num_final_digital_outputs
                         , NULL, 0
                         ,
                         &Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_AOVoltages
                         [0]
                         , NULL
                         , (t_boolean *)
                         &Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_DOBits[0]
                         , NULL
                         );
      if (result == -QERR_HIL_WRITE_NOT_SUPPORTED) {
        t_error local_result;
        result = 0;

        /* The hil_write operation is not supported by this card. Write final outputs for each channel type */
        if (num_final_analog_outputs > 0) {
          local_result = hil_write_analog
            (Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card,
             Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_AOChannels,
             num_final_analog_outputs,
             &Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_AOVoltages[0]);
          if (local_result < 0) {
            result = local_result;
          }
        }

        if (num_final_digital_outputs > 0) {
          local_result = hil_write_digital
            (Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card,
             Copy_of_TRACKING_CONTROL_KPES_P.HILInitialize_DOChannels,
             num_final_digital_outputs, (t_boolean *)
             &Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_DOBits[0]);
          if (local_result < 0) {
            result = local_result;
          }
        }

        if (result < 0) {
          msg_get_error_messageA(NULL, result, _rt_error_message, sizeof
            (_rt_error_message));
          rtmSetErrorStatus(Copy_of_TRACKING_CONTROL_KPE_M, _rt_error_message);
        }
      }
    }

    hil_task_delete_all(Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card);
    hil_monitor_delete_all(Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card);
    hil_close(Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card);
    Copy_of_TRACKING_CONTROL_KPE_DW.HILInitialize_Card = NULL;
  }
}

